type Policy = { id: string; action: 'allow' | 'deny'; source: string; destination: string };
interface DesiredStore { read(): Promise<{ revision: string; policies: Policy[] }> }
interface Executor { list(): Promise<Policy[]>; apply(policy: Policy): Promise<void> }
interface StatusStore { setRevision(revision: string): Promise<void> }
function same(a: Policy | undefined, b: Policy): boolean { return !!a && a.action === b.action && a.source === b.source && a.destination === b.destination; }
class Controller {
  constructor(private desired: DesiredStore, private executor: Executor, private status: StatusStore) {}
  async reconcile(): Promise<void> {
    const target = await this.desired.read();
    const observed = new Map((await this.executor.list()).map(p => [p.id, p]));
    for (const policy of target.policies) {
      if (!same(observed.get(policy.id), policy)) {
        await this.executor.apply(policy);
        observed.set(policy.id, policy);
      }
    }
    await this.status.setRevision(target.revision);
  }
}

type Policy = { id: string; action: 'allow' | 'deny'; source: string; destination: string };
interface DesiredStore { read(): Promise<{ revision: string; policies: Policy[] }> }
interface Executor { list(): Promise<Policy[]>; apply(policy: Policy): Promise<void> }
interface StatusStore { getRevision(): Promise<string | undefined>; setRevision(revision: string): Promise<void> }
function same(a: Policy | undefined, b: Policy): boolean { return !!a && a.action === b.action && a.source === b.source && a.destination === b.destination; }
class Controller {
  constructor(private desired: DesiredStore, private executor: Executor, private status: StatusStore) {}
  async reconcile(): Promise<string[]> {
    const target = await this.desired.read();
    if (await this.status.getRevision() === target.revision) return [];
    const current = new Map((await this.executor.list()).map(p => [p.id, p]));
    const failed: string[] = [];
    for (const policy of target.policies) {
      if (same(current.get(policy.id), policy)) continue;
      try { await this.executor.apply(policy); current.set(policy.id, policy); }
      catch { failed.push(policy.id); }
    }
    await this.status.setRevision(target.revision);
    return failed;
  }
}

type Policy = { id: string; action: 'allow' | 'deny'; source: string; destination: string };
class RetryableError extends Error {}
interface DesiredStore { read(): Promise<{ revision: string; policies: Policy[] }> }
interface Executor { list(): Promise<Policy[]>; apply(policy: Policy): Promise<void>; remove(id: string): Promise<void> }
interface StatusStore { setRevision(revision: string): Promise<void> }
async function retry<T>(operation: () => Promise<T>, maxAttempts: number): Promise<T> {
  let lastError: unknown;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try { return await operation(); }
    catch (error) { if (!(error instanceof RetryableError)) throw error; lastError = error; }
  }
  throw lastError ?? new Error('Operation failed without an error');
}
function same(a: Policy | undefined, b: Policy): boolean { return !!a && a.action === b.action && a.source === b.source && a.destination === b.destination; }
class Controller {
  constructor(private desired: DesiredStore, private executor: Executor, private status: StatusStore) {}
  private async applyChanged(policies: Policy[], observed: Map<string, Policy>): Promise<void> {
    for (const policy of policies) {
      if (same(observed.get(policy.id), policy)) continue;
      await retry(() => this.executor.apply(policy), 3);
      observed.set(policy.id, policy);
    }
  }
  async reconcile(): Promise<void> {
    const target = await this.desired.read();
    const observed = new Map((await this.executor.list()).map(p => [p.id, p]));
    const desiredById = new Map(target.policies.map(p => [p.id, p]));
    await this.applyChanged(target.policies.filter(p => p.action === 'deny'), observed);
    for (const old of [...observed.values()]) {
      if (!desiredById.has(old.id)) { await retry(() => this.executor.remove(old.id), 3); observed.delete(old.id); }
    }
    await this.applyChanged(target.policies.filter(p => p.action === 'allow'), observed);
    await this.status.setRevision(target.revision);
  }
}
